// keeps the unresolved behavior identity explicit.

typedef unsigned int UnsignedInt;

__forceinline bool rva002D9F90Test( UnsignedInt flags, UnsignedInt mask )
{
	return flags & mask;
}

class Rva002D9F90Owner
